#!/bin/bash
# Regenerate ext/standard/var_unserializer.c of a PHP 5.2.17 (release tarball based) tree the way
# the release was built: re2c 0.13.5 with -b -i (no #line). The "Generated by" line and the $Id$
# line are kept from the current file so patches only carry real changes.
# usage: regen-re2c.sh <php-src-dir>   (Windows path, e.g. C:/php-bp/wt52)
export MSYS_NO_PATHCONV=1
docker run --rm -v "$1":/w php52-ci bash -c 'cd /w && f=ext/standard/var_unserializer.c &&
  l1=$(sed -n 1p $f) && l20=$(sed -n 20p $f) &&
  re2c -b -i -o $f.new ext/standard/var_unserializer.re &&
  awk -v l1="$l1" -v l20="$l20" "NR==1{print l1;next} NR==20{print l20;next} {print}" $f.new > $f && rm $f.new'
